head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};

scwin.ibx_openPopup_onclick1 = function(e) {
	var uri = "/sample/common_link/wframe_popup_setSrc_modal_remain_WESD-275_(WSQ-4433)_sub.xml";
	var opts = {
		"id": "wframePopup",
		"type": "wframePopup",
		"width": "700px",
		"height": "250px",
		"top": 150,
		"left": 150,
		"popupName": "wframePopup",
		"modal": true,
		"title": "wframe popup",
		"foldOnMinimized": true,
		"popupAutoClose": true,
		"windowDragMove": true
	};
	scwin.$w.openPopup(uri, opts);
};
